SELECT 1, '系统管理', 0, 100, 'system', '', '', '', 1, 0, 'M', '0', '0', '', 'system', '系统管理目录' FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM sys_menu WHERE menu_id = 1);
