-- ############ B 段：角色授权同步 ############

-- B1. 管理员（role_id=1）补齐全量菜单授权
INSERT INTO sys_role_menu (role_id, menu_id)
SELECT 1, m.menu_id FROM sys_menu m
WHERE NOT EXISTS (SELECT 1 FROM sys_role_menu x WHERE x.role_id = 1 AND x.menu_id = m.menu_id);

-- B2. 其他启用角色：角色已授权某父菜单时，自动补授其新子菜单（跳过 admin）
INSERT INTO sys_role_menu (role_id, menu_id)
SELECT r.role_id, m.menu_id
FROM sys_menu m
JOIN sys_role r ON r.role_id <> 1 AND r.status = '0' AND r.del_flag = '0'
JOIN sys_role_menu rp ON rp.role_id = r.role_id AND rp.menu_id = m.parent_id
WHERE NOT EXISTS (SELECT 1 FROM sys_role_menu x WHERE x.role_id = r.role_id AND x.menu_id = m.menu_id);

